\end{tikzpicture}[/tikz]

$ABCD$ is a cyclic quadrilateral with centre $O$. Side $CD$ is extended beyond $D$ to $E$. $\angle ADE=72^{\circ}$ and $\angle BAD=98^{\circ}$. Find $\angle ADC$, $\angle ABC$, $\angle BCD$ and the smaller central angle $\angle AOC$.
[tikz]\begin{tikzpicture}[draw=black,text=black,every node/.style={font=\fontsize{10}{12}\selectfont}]
\usetikzlibrary{calc}
\coordinate (O) at (0,0);\coordinate (A) at (150:2);\coordinate (B) at (50:2);\coordinate (C) at (294:2);\coordinate (D) at (214:2);\coordinate (E) at ($(C)!1.3!(D)$);
\draw (O) circle (2);\draw (A)--(B)--(C)--(D)--cycle;\draw (D)--(E);\draw (A)--(O)--(C);\fill (O) circle (0.035);
\node[above left] at (A) {$A$};\node[above right] at (B) {$B$};\node[below right] at (C) {$C$};\node[below left] at (D) {$D$};\node[left] at (E) {$E$};\node[right] at (O) {$O$};
\end{tikzpicture}[/tikz]

